    if (dealRecord["customerName"] === undefined || dealRecord["customerName"] === null) { throw new Error("customerName is required"); }
    if (invoiceRecord["invoiceId"] === undefined || invoiceRecord["invoiceId"] === null) { throw new Error("invoiceId is required"); }
    if (invoiceRecord["dealId"] === undefined || invoiceRecord["dealId"] === null) { throw new Error("dealId is required"); }
    if (invoiceRecord["invoiceAmount"] === undefined || invoiceRecord["invoiceAmount"] === null) { throw new Error("invoiceAmount is required"); }
    const currentDate = dealRecord.currentDate;
    
    const invoiceStatus = invoiceRecord.invoiceStatus;
    const dealStatus = dealRecord.dealStatus;
  
    // ズレの検出：請求書が未発行の場合
    const mismatchDetected = invoiceStatus === "unissued";
    const mismatchType = mismatchDetected ? "unissued" : "none";
  
    // 決算期限までの営業日数を計算
    const daysUntilDeadline = calculateBusinessDaysDifference(
      currentDate,
      settlementDeadline
    );
  
    // 段階的SLAの判定
    // 決算期限1営業日前：営業担当者への対応指示SLA（高優先度）
    const isOneBusinessDayBefore = daysUntilDeadline === 1;
    const slaLevel = mismatchDetected && isOneBusinessDayBefore ? "high" : "normal";
    const slaDescription =
      slaLevel === "high" ? "営業担当者への対応指示は期限1営業日前" : "通常対応";
  
    // 対応指示の生成
    const actionRequired = mismatchDetected && isOneBusinessDayBefore;
    const actionType = actionRequired ? "urgent" : "normal";
    const actionDescription = actionRequired
      ? "請求書作成・発行を実行してください。決算期限が明日に迫っています。"
      : "通常の対応を継続してください。";
    const priority = actionRequired ? "high" : "normal";
    const warningFlag = actionRequired;
  
    // 発行タイミングの検証
    const issuanceTimingValid = true; // 現在時点で遅延なし
    const delayMinutes = 0; // 遅延なし
  
    // SLAステージの判定
    const slaStage = actionRequired ? "operator_action_instruction" : "normal";
    const expectedActionTiming = actionRequired ? "immediate" : "standard";
  
    // 検出ログの構築
    const detectionLog = {
      timestamp: currentDate.toISOString(),
      dealId: dealRecord.dealId,
      mismatchType,
      slaLevel,
      actionRequired,
      dealStatus,
      invoiceStatus,
      daysUntilDeadline,
      instructionContent: {
        dealAmount: dealRecord.dealAmount,
        customerId: dealRecord.customerId,
        actionType,
        priority,
      },
    };
  
