/* AIVIC_FUNCTION_BUNDLE_START owner=detectSalesRevenueRecognitionBillingDiscrepancy exports=detectSalesRevenueRecognitionBillingDiscrepancy */
const __aivicBundle_31_detectSalesRevenueRecognitionBillingDiscrepancy = (() => {
  function detectSalesRevenueRecognitionBillingDiscrepancy(input: {
    revenueRecognitionDate: Date;
    billingDate: Date;
    toleranceDaysDelay: number;
  }): {
    status: string;
    alertLevel: number;
    isWithinTolerance: boolean;
    discrepancyDays: number;
    errorMessage?: string;
  } {
    const { revenueRecognitionDate, billingDate, toleranceDaysDelay } = input;
  
    const revenueTime = revenueRecognitionDate.getTime();
    const billingTime = billingDate.getTime();
    const millisecondsPerDay = 24 * 60 * 60 * 1000;
  
    const discrepancyDays = Math.round(
      (revenueTime - billingTime) / millisecondsPerDay
    );
  
    const isWithinTolerance = Math.abs(discrepancyDays) <= toleranceDaysDelay;
  
    let status: string;
    let alertLevel: number;
  
    if (isWithinTolerance) {
      status = "OK";
      alertLevel = 0;
    } else {
      status = "WARNING";
      alertLevel = 1;
    }
  
    return {
      status,
      alertLevel,
      isWithinTolerance,
      discrepancyDays,
    };
  }
  return { detectSalesRevenueRecognitionBillingDiscrepancy };
})();
export const detectSalesRevenueRecognitionBillingDiscrepancy = __aivicBundle_31_detectSalesRevenueRecognitionBillingDiscrepancy.detectSalesRevenueRecognitionBillingDiscrepancy;
/* AIVIC_FUNCTION_BUNDLE_END owner=detectSalesRevenueRecognitionBillingDiscrepancy */

/* AIVIC_FUNCTION_BUNDLE_START owner=validateMigrationDataConsistency exports=validateMigrationDataConsistency */
const __aivicBundle_32_validateMigrationDataConsistency = (() => {
  function validateMigrationDataConsistency(input: {
    targetPeriodStart: Date;
    targetPeriodEnd: Date;
    salesRevenue: Array<{
      id: string;
      dealId: string;
      customerId: string;
      amount: number;
      quantity: number;
      recordedDate: Date;
      status: string;
    }>;
    billingStatus: Array<{
      id: string;
      dealId: string;
      customerId: string;
      amount: number;
      quantity: number;
      invoiceDate: Date;
      status: string;
    }>;
  }): MigrationValidationResult {
    if (input["targetPeriodStart"] === undefined || input["targetPeriodStart"] === null) { throw new Error("targetPeriodStart is required"); }
    if (input["targetPeriodEnd"] === undefined || input["targetPeriodEnd"] === null) { throw new Error("targetPeriodEnd is required"); }
    const { salesRevenue, billingStatus } = input;
  
    const totalSalesRecords = salesRevenue.length;
    const totalBillingRecords = billingStatus.length;
  
    const totalSalesAmount = salesRevenue.reduce((sum, record) => sum + record.amount, 0);
    const totalBillingAmount = billingStatus.reduce((sum, record) => sum + record.amount, 0);
  
    const amountDifference = Math.abs(totalSalesAmount - totalBillingAmount);
  
    const mismatches: Array<{
      salesId?: string;
      billingId?: string;
      dealId?: string;
      amountDifference?: number;
      dateDifference?: number;
    }> = [];
  
    const billingByDealId = new Map<string, typeof billingStatus[0]>();
    billingStatus.forEach((bill) => {
      billingByDealId.set(bill.dealId, bill);
    });
  
    let matchedCount = 0;
  
    salesRevenue.forEach((sale) => {
      const correspondingBill = billingByDealId.get(sale.dealId);
  
      if (!correspondingBill) {
        mismatches.push({
          salesId: sale.id,
          dealId: sale.dealId,
          amountDifference: sale.amount,
        });
      } else {
        const amountMatch = sale.amount === correspondingBill.amount;
        const quantityMatch = sale.quantity === correspondingBill.quantity;
        const customerMatch = sale.customerId === correspondingBill.customerId;
  
        if (amountMatch && quantityMatch && customerMatch) {
          matchedCount++;
        } else {
          mismatches.push({
            salesId: sale.id,
            billingId: correspondingBill.id,
            dealId: sale.dealId,
            amountDifference: sale.amount - correspondingBill.amount,
            dateDifference: Math.floor(
              (correspondingBill.invoiceDate.getTime() - sale.recordedDate.getTime()) /
                (1000 * 60 * 60 * 24)
            ),
          });
        }
      }
    });
  
    billingStatus.forEach((bill) => {
      const correspondingSale = salesRevenue.find((sale) => sale.dealId === bill.dealId);
      if (!correspondingSale) {
        mismatches.push({
          billingId: bill.id,
          dealId: bill.dealId,
          amountDifference: bill.amount,
        });
      }
    });
  
    const unmatchedCount = mismatches.length;
    const reconciliationRate =
      totalSalesRecords + totalBillingRecords > 0
        ? Math.round((matchedCount / Math.max(totalSalesRecords, totalBillingRecords)) * 100)
        : 0;
    const isCompletelyReconciled = unmatchedCount === 0 && amountDifference === 0;
  
    return {
      totalSalesRecords,
      totalBillingRecords,
      totalSalesAmount,
      totalBillingAmount,
      matchedCount,
      unmatchedCount,
      reconciliationRate,
      isCompletelyReconciled,
      mismatches,
      amountDifference,
    };
  }
  return { validateMigrationDataConsistency };
})();
export const validateMigrationDataConsistency = __aivicBundle_32_validateMigrationDataConsistency.validateMigrationDataConsistency;
/* AIVIC_FUNCTION_BUNDLE_END owner=validateMigrationDataConsistency */

